const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdentChar = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  function adv() {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = (Math.floor((col - 1) / 4) + 1) * 4 + 1
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  function number(sl, sc) {
    const start = i
    let ok = true
    const digitsRun = (pred) => {
      let count = 0
      while (i < n) {
        if (pred(cs[i])) { adv(); count++ }
        else if (cs[i] === '_' && count > 0 && pred(cs[i + 1])) adv()
        else break
      }
      return count
    }
    const p = cs[i + 1]
    if (cs[i] === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
      const lc = p.toLowerCase()
      const pred = lc === 'x' ? isHex : lc === 'b' ? (c) => c === '0' || c === '1' : (c) => c >= '0' && c <= '7' && c.length === 1
      adv(); adv()
      if (digitsRun(pred) === 0) ok = false
    } else {
      digitsRun(isDigit)
      if (cs[i] === '.' && isDigit(cs[i + 1])) { adv(); digitsRun(isDigit) }
      if (cs[i] === 'e' || cs[i] === 'E') {
        if (isDigit(cs[i + 1])) { adv(); digitsRun(isDigit) }
        else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { adv(); adv(); digitsRun(isDigit) }
      }
    }
    if (i < n && isIdentChar(cs[i])) ok = false
    if (!ok) {
      while (i < n && isIdentChar(cs[i])) adv()
      throw new ScanError(sl, sc, `invalid number ${cs.slice(start, i).join('')}`)
    }
    tokens.push({ line: sl, col: sc, kind: 'number', body: cs.slice(start, i).join('') })
  }

  function string(sl, sc) {
    adv()
    let out = ''
    for (;;) {
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      const c = cs[i]
      if (c === '\n') throw new ScanError(line, col, 'newline in string')
      if (c === '"') { adv(); break }
      if (c !== '\\') { out += adv(); continue }
      const bl = line, bc = col
      adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      const e = cs[i]
      const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
      if (e === 'n') { adv(); out += '\n' }
      else if (e === 't') { adv(); out += '\t' }
      else if (e === 'r') { adv(); out += '\r' }
      else if (e === '\\') { adv(); out += '\\' }
      else if (e === '"') { adv(); out += '"' }
      else if (e === '0') { adv(); out += '\0' }
      else if (e === 'x') {
        if (!isHex(cs[i + 1]) || !isHex(cs[i + 2])) throw bad()
        out += String.fromCharCode(parseInt(cs[i + 1] + cs[i + 2], 16))
        advN(3)
      } else if (e === 'u') {
        if (cs[i + 1] !== '{') throw bad()
        let j = i + 2
        let h = ''
        while (isHex(cs[j])) h += cs[j++]
        if (h === '' || cs[j] !== '}') throw bad()
        const v = parseInt(h.replace(/^0+(?=.)/, ''), 16)
        if (h.replace(/^0+/, '').length > 6 || v > 0x10ffff) throw bad()
        out += String.fromCodePoint(v)
        advN(j + 1 - i)
      } else throw bad()
    }
    tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(out) })
  }

  while (i < n) {
    const c = cs[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let s = ''
      while (i < n && cs[i] !== '"') s += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(s) })
      continue
    }
    if (isLetter(c) || c === '_') {
      const st = i
      while (i < n && isIdentChar(cs[i])) adv()
      const w = cs.slice(st, i).join('')
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(w) ? 'keyword' : 'ident', body: w })
      continue
